import{_ as n,C as o,o as l,c as i,E as r,a3 as p,w as c,j as t,a}from"./chunks/framework.CCylkYel.js";const h="/screens/devices/looper.png",f=JSON.parse('{"title":"Looper","description":"","frontmatter":{"title":"Looper","pageClass":"device-doc"},"headers":[],"relativePath":"devices/looper.md","filePath":"devices/looper.md"}'),u={name:"devices/looper.md"};function g(m,e,b,v,E,O){const s=o("DeviceHeading"),d=o("ManualRelated");return l(),i("div",null,[r(s,{slug:"looper",title:"Looper"}),e[1]||(e[1]=p('<p>Loop and overdub MIDI</p><p><img src="'+h+'" alt="Looper: MODE ONCE, QUANTIZE 1/16, LENGTH 4, playing bar 2." class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Record a phrase, loop it, and play over it.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Put a <a href="/devices/clock">Clock</a> before it in the rack. Without one it doesn&#39;t play, and <strong>RECORD</strong> switches back off.</p></div><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>BYPASS</td><td>OFF / ON</td><td>ON: recording and playback stop; the loop is kept. See <a href="/devices/#bypass">BYPASS</a>.</td></tr><tr><td>RECORD</td><td>IDLE / RECORDING</td><td>Tap <strong>Select</strong> to arm a take. Tap again to stop recording and play the loop.</td></tr><tr><td>RESET</td><td>—</td><td>Tap <strong>Select</strong> to clear the loop.</td></tr><tr><td>MODE</td><td>STOP – OVERDUB</td><td>What <strong>RECORD</strong> does.</td></tr><tr><td>QUANTIZE</td><td>OFF – 1/32</td><td>Moves the start of each recorded note to the nearest grid step. Lengths stay as played.</td></tr><tr><td>LENGTH</td><td>1 – 16</td><td>Loop length in bars.</td></tr><tr><td>COUNTDOWN</td><td>1 BAR – 4 BARS</td><td><strong>1 BAR</strong> starts the take on the next bar line. Each extra bar waits one bar more.</td></tr></tbody></table></div><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="mode" tabindex="-1">MODE <a class="header-anchor" href="#mode" aria-label="Permalink to &quot;MODE&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Value</th><th>What it does</th></tr></thead><tbody><tr><td>STOP</td><td>Nothing records or plays. The loop is kept.</td></tr><tr><td>ONCE</td><td><strong>RECORD</strong> clears the loop, records <strong>LENGTH</strong> bars, then plays them.</td></tr><tr><td>OVERDUB</td><td><strong>RECORD</strong> adds notes on top of the loop on every pass, until you tap it again.</td></tr></tbody></table><p><strong>ONCE</strong> and <strong>OVERDUB</strong> start playing the loop as soon as you pick them. MIDI Start, Stop or Continue cancels a take in progress.</p>',11)),r(d,null,{default:c(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"/racks/"},"Racks"),a(" — build a chain of devices")]),t("li",null,[t("a",{href:"/concepts/mapping"},"Mapping"),a(" — put a device setting on a knob or an LFO")]),t("li",null,[t("a",{href:"/concepts/modulation"},"Modulation"),a(" — move a setting while you play")])],-1)])]),_:1})])}const R=n(u,[["render",g]]);export{f as __pageData,R as default};
